CREATE TABLE customer_source_coverage(organization_id TEXT PRIMARY KEY REFERENCES organization(id),complete_from TEXT NOT NULL,complete_through TEXT NOT NULL,reason TEXT NOT NULL,version INTEGER NOT NULL DEFAULT 1,updated_by TEXT NOT NULL,updated_at TEXT NOT NULL,CHECK(complete_through>=complete_from));
CREATE TABLE customer_tier_rule(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL REFERENCES organization(id),name TEXT NOT NULL,method TEXT NOT NULL CHECK(method IN('nominal','percentile','custom')),parameters_json TEXT NOT NULL,area_id TEXT,status TEXT NOT NULL DEFAULT 'draft' CHECK(status IN('draft','approved','retired')),version INTEGER NOT NULL DEFAULT 1,created_by TEXT NOT NULL,created_at TEXT NOT NULL,approved_by TEXT,approved_at TEXT,UNIQUE(organization_id,id));
CREATE UNIQUE INDEX customer_tier_active ON customer_tier_rule(organization_id,COALESCE(area_id,'')) WHERE status='approved';
CREATE TABLE customer_segmentation_run(id TEXT PRIMARY KEY,organization_id TEXT NOT NULL,cutoff TEXT NOT NULL,source_epoch INTEGER NOT NULL,coverage_version INTEGER NOT NULL,rule_versions_json TEXT NOT NULL,created_at TEXT NOT NULL,UNIQUE(organization_id,id));
CREATE TABLE customer_status_snapshot(run_id TEXT NOT NULL,organization_id TEXT NOT NULL,customer_id TEXT NOT NULL,cutoff TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('Aktif','Churn','New','Unknown')),observed_status TEXT NOT NULL,provisional INTEGER NOT NULL,last_invoice_date TEXT,net_minor INTEGER NOT NULL,tier TEXT,rule_id TEXT,rule_version INTEGER,cohort_size INTEGER NOT NULL,PRIMARY KEY(run_id,customer_id),FOREIGN KEY(run_id) REFERENCES customer_segmentation_run(id));
CREATE INDEX customer_status_cutoff ON customer_status_snapshot(organization_id,customer_id,cutoff);
